    @After public void after()throws Exception{for(ActivityController<?> c:owners)c.pause().stop().destroy();java.util.concurrent.CountDownLatch done=new java.util.concurrent.CountDownLatch(1);HomeWidget.request(app,done::countDown);assertTrue(done.await(15,java.util.concurrent.TimeUnit.SECONDS));ProbeState.clear();}
    WidgetAppearance.Settings own(int opacity){return new WidgetAppearance.Settings(WidgetAppearance.Mode.CUSTOM,opacity,0xff19252a,0xffeeeeee,WidgetAppearance.TextTone.AUTO,false);}
    void save(int id,WidgetAppearance.Settings value)throws Exception{WidgetAppearance.save(app,id,WidgetAppearance.load(app,id).revision,value);}
    byte[] output()throws Exception{return Files.readAllBytes(new File(app.getFilesDir(),OutputPreferenceStore.FILE_NAME).toPath());}
    ActivityController<WidgetConfigureActivity> open(int id){ActivityController<WidgetConfigureActivity> c=Robolectric.buildActivity(WidgetConfigureActivity.class,new Intent(app,WidgetConfigureActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id)).create().start().resume().visible();owners.add(c);return c;}
    static List<View> all(View root){List<View> list=new ArrayList<>();list.add(root);if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++)list.addAll(all(((ViewGroup)root).getChildAt(i)));return list;}
    View tag(Activity a,String tag){for(View v:all(a.getWindow().getDecorView()))if(tag.equals(v.getTag()))return v;throw new AssertionError(tag);}
    Button action(Activity a,String description){for(View v:all(a.getWindow().getDecorView()))if(v instanceof Button&&description.equals(v.getContentDescription()))return (Button)v;throw new AssertionError(description);}
    @Test public void settingsAreIndependentPerWidgetAndDoNotRewriteOutputOrAlarmState()throws Exception{byte[] old=output();ConfigurationSnapshot profile=ProfileController.capture(app);save(first,own(37));save(second,new WidgetAppearance.Settings(WidgetAppearance.Mode.APP,80,0xffabcdef,0xff123456,WidgetAppearance.TextTone.LIGHT,true));assertEquals(own(37),WidgetAppearance.load(app,first).settings);assertEquals(80,WidgetAppearance.load(app,second).settings.opacity);assertEquals(1,WidgetAppearance.load(app,first).revision);assertArrayEquals(old,output());assertFalse(LivePreferences.alarms(app));assertFalse(new File(app.getFilesDir(),"live-receipt-runtime-v1").exists());ProfileController.apply(app,profile);assertEquals(own(37),WidgetAppearance.load(app,first).settings);assertEquals(80,WidgetAppearance.load(app,second).settings.opacity);}
    @Test public void oldWidgetsRetainTheirThemeAndSwitchRowWithoutAMigrationWrite(){AppAppearance.set(app,AppAppearance.Mode.DARK);app.getSharedPreferences(HomeWidget.PREFS,0).edit().putBoolean("controls_"+first,false).commit();Map<String,?> before=new HashMap<>(app.getSharedPreferences(HomeWidget.PREFS,0).getAll());WidgetAppearance.Settings s=WidgetAppearance.load(app,first).settings;assertEquals(WidgetAppearance.Mode.APP,s.mode);assertFalse(s.controls);assertTrue(WidgetAppearance.palette(app,s).dark);assertEquals(before,app.getSharedPreferences(HomeWidget.PREFS,0).getAll());}
    @Test public void aNewEditorDefaultsToSystemButAnOldWidgetKeepsItsAppChoice(){WidgetConfigureActivity a=open(first).get();assertEquals(9400,((RadioGroup)tag(a,"widget_modes")).getCheckedRadioButtonId());app.getSharedPreferences(HomeWidget.PREFS,0).edit().putBoolean("controls_"+second,true).commit();WidgetConfigureActivity old=open(second).get();assertEquals(9401,((RadioGroup)tag(old,"widget_modes")).getCheckedRadioButtonId());assertFalse(WidgetAppearance.configured(app,first));}
    @Test public void savedColorsSurviveStyleChangesAndRestorationIncludingOverlappingIds()throws Exception{save(first,own(42));save(second,new WidgetAppearance.Settings(WidgetAppearance.Mode.SYSTEM,73,0xffabcdef,0xff123456,WidgetAppearance.TextTone.DARK,true));WidgetAppearance.Snapshot a=WidgetAppearance.load(app,first),b=WidgetAppearance.load(app,second);WidgetAppearance.restore(app,new int[]{first,second},new int[]{second,73});assertEquals(a.settings,WidgetAppearance.load(app,second).settings);assertEquals(b.settings,WidgetAppearance.load(app,73).settings);assertEquals(b.revision,WidgetAppearance.load(app,73).revision);assertFalse(WidgetAppearance.configured(app,first));WidgetAppearance.delete(app,new int[]{second});assertFalse(WidgetAppearance.configured(app,second));assertEquals(b.settings,WidgetAppearance.load(app,73).settings);}
    @Test public void staleOrDeletedWidgetsCannotOverwriteAnotherEdit()throws Exception{long revision=WidgetAppearance.load(app,first).revision;save(first,own(50));try{WidgetAppearance.save(app,first,revision,own(0));fail();}catch(IOException expected){}assertEquals(50,WidgetAppearance.load(app,first).settings.opacity);try{WidgetAppearance.save(app,999,0,own(0));fail();}catch(IOException expected){}assertFalse(WidgetAppearance.configured(app,999));}
    @Test public void malformedAppearanceFallsBackWithoutWritingOrTouchingOtherPreferences(){app.getSharedPreferences(HomeWidget.PREFS,0).edit().putString("style_"+first,"INVALID").putString("opacity_"+first,"bad").putInt("textTone_"+first,99).commit();Map<String,?> old=new HashMap<>(app.getSharedPreferences(HomeWidget.PREFS,0).getAll());WidgetAppearance.Settings s=WidgetAppearance.load(app,first).settings;assertEquals(WidgetAppearance.Mode.APP,s.mode);assertEquals(100,s.opacity);assertEquals(WidgetAppearance.TextTone.AUTO,s.textTone);assertEquals(old,app.getSharedPreferences(HomeWidget.PREFS,0).getAll());for(int n:new int[]{-1,101})try{own(n);fail();}catch(IllegalArgumentException expected){}for(String color:new String[]{"red","#GG0011","#AABBCCDD","#fff"})try{WidgetColorDialog.parse(color);fail();}catch(IllegalArgumentException expected){}assertEquals(0xffaabbcc,WidgetColorDialog.parse("#aabbcc"));}
    @Test public void systemPaletteFollowsSystemNightModeEvenWhenTheAppForcesTheOpposite(){for(boolean dark:new boolean[]{false,true}){Configuration c=new Configuration(app.getResources().getConfiguration());c.uiMode=(c.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|(dark?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO);app.getResources().updateConfiguration(c,app.getResources().getDisplayMetrics());AppAppearance.set(app,dark?AppAppearance.Mode.LIGHT:AppAppearance.Mode.DARK);WidgetAppearance.Palette system=WidgetAppearance.palette(app,WidgetAppearance.Settings.defaults(WidgetAppearance.Mode.SYSTEM));assertEquals(dark,system.dark);assertEquals(!dark,WidgetAppearance.palette(app,WidgetAppearance.Settings.defaults(WidgetAppearance.Mode.APP)).dark);int expected=Build.VERSION.SDK_INT>=31?app.getColor(dark?android.R.color.system_neutral1_900:android.R.color.system_neutral1_50):new AppAppearance.Colors(dark).surface;assertEquals(expected,system.surface);}}
    @Test public void everyRenderReadsTheCurrentSystemResourcesAndOpacityDoesNotDimTheInk(){int[] surface={0xffaaeeff};android.content.res.Resources resources=new android.content.res.Resources(app.getAssets(),app.getResources().getDisplayMetrics(),app.getResources().getConfiguration()){@Override public int getColor(int id,android.content.res.Resources.Theme theme){return id==android.R.color.system_neutral1_50?surface[0]:super.getColor(id,theme);}};Context palette=new ContextWrapper(app){@Override public android.content.res.Resources getResources(){return resources;}};WidgetAppearance.Settings s=WidgetAppearance.Settings.defaults(WidgetAppearance.Mode.SYSTEM);if(Build.VERSION.SDK_INT>=31){assertEquals(surface[0],WidgetAppearance.palette(palette,s).surface);surface[0]=0xffffccdd;assertEquals(surface[0],WidgetAppearance.palette(palette,s).surface);}WidgetAppearance.Palette colors=WidgetAppearance.palette(app,own(0));assertEquals(0,Color.alpha(colors.background(0)));assertEquals(128,Color.alpha(colors.background(50)));assertEquals(255,Color.alpha(colors.ink));assertEquals(0xffeeeeee,colors.ink);}
    @Test public void canceledAndRotatedDraftsNeverPersistOrArmOutput()throws Exception{byte[] bytes=output();ActivityController<WidgetConfigureActivity> c=open(first);WidgetConfigureActivity a=c.get();((SeekBar)tag(a,"widget_opacity")).setProgress(36);((RadioButton)a.findViewById(9402)).performClick();ReflectionHelpers.setField(a,"background",0xff112233);Bundle state=new Bundle();c.saveInstanceState(state).pause().stop().destroy();owners.remove(c);ActivityController<WidgetConfigureActivity> next=Robolectric.buildActivity(WidgetConfigureActivity.class,new Intent(app,WidgetConfigureActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,first)).create(state).start().resume().visible();owners.add(next);assertEquals(36,((SeekBar)tag(next.get(),"widget_opacity")).getProgress());assertEquals(9402,((RadioGroup)tag(next.get(),"widget_modes")).getCheckedRadioButtonId());assertEquals(0xff112233,(int)ReflectionHelpers.getField(next.get(),"background"));assertFalse(WidgetAppearance.configured(app,first));next.get().onBackPressed();assertNotNull(ShadowAlertDialog.getLatestAlertDialog());assertArrayEquals(bytes,output());assertFalse(LivePreferences.alarms(app));}
    @Test public void colorPickerAndSaveApplyOnlyToTheChosenWidget()throws Exception{WidgetConfigureActivity a=open(first).get();((RadioButton)a.findViewById(9402)).performClick();((Button)tag(a,"widget_background_color")).performClick();AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();shadowOf(Looper.getMainLooper()).idle();EditText hex=null;for(View v:all(dialog.getWindow().getDecorView()))if(v instanceof EditText)hex=(EditText)v;assertNotNull(hex);hex.setText("#ABCDEF");dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();shadowOf(Looper.getMainLooper()).idle();assertFalse(WidgetAppearance.configured(app,first));((SeekBar)tag(a,"widget_opacity")).setProgress(44);action(a,"Speichern").performClick();assertEquals(0xffabcdef,WidgetAppearance.load(app,first).settings.background);assertEquals(44,WidgetAppearance.load(app,first).settings.opacity);assertFalse(WidgetAppearance.configured(app,second));assertEquals(Activity.RESULT_OK,shadowOf(a).getResultCode());assertEquals(first,shadowOf(a).getResultIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1));}
